/* ── SESSION DETAIL ── */
async function selectSession(file){
  activeFile=file;
  renderList();
  const s=sessions.find(s=>s.file===file);
  const hdr=document.getElementById('chat-header');
  hdr.querySelector('.ch-title').textContent=s?(s.name||s.first_user||'Sesión'):'';
  hdr.querySelector('.ch-id').textContent=s?s.id:'';
  hdr.querySelector('.ch-id').title='pi --session '+s.id;
  hdr.querySelector('.ch-cost').textContent=s&&s.total_cost>0?`$${s.total_cost.toFixed(4)} | ${s.total_tokens.toLocaleString()} tk`:'';

  const body=document.getElementById('chat-body');
  body.innerHTML='<div style="text-align:center;padding:40px;color:var(--muted)"><i class="ph ph-spinner ph-spin" style="font-size:1.5rem"></i></div>';

  try{
    const r=await fetch('/api/session?file='+encodeURIComponent(file));
    const lines=await r.json();
    renderChat(lines);
  }catch(e){body.innerHTML='<div class="welcome">Error al cargar sesión</div>'}
}

function renderChat(lines){
  const body=document.getElementById('chat-body');
  let html='',lastRole='',pendingToolResults={};
  for(const line of lines){
    try{var e=JSON.parse(line)}catch(_){continue}
    if(e.type==='session')continue;

    if(e.type==='model_change'){
      html+=`<div class="sys-event"><i class="ph ph-cpu"></i> ${esc(e.provider)} / ${esc(e.modelId)}</div>`;
    }else if(e.type==='thinking_level_change'){
      html+=`<div class="sys-event"><i class="ph ph-brain"></i> thinking: ${esc(e.thinkingLevel)}</div>`;
    }else if(e.type==='compaction'){
      html+=`<div class="sys-event"><i class="ph ph-scissors"></i> compactado (${e.tokensBefore} tokens)</div>`;
    }else if(e.type==='message'){
      const msg=e.message||{},role=msg.role;
      let txt='',toolCalls=[];
      const content=msg.content;
      if(Array.isArray(content)){
        for(const c of content){
          if(c.type==='text') txt+=esc(c.text);
          else if(c.type==='thinking') txt+=`<details class="think-block"><summary><i class="ph ph-brain"></i> Pensando...</summary><div class="think-content">${esc(c.thinking||'')}</div></details>`;
          else if(c.type==='toolCall') toolCalls.push(c);
        }
      }else if(typeof content==='string') txt=esc(content);
      else if(!content) txt='';

      const usage=msg.usage||{};
      const costStr=usage.cost?.total?`<span>$${usage.cost.total.toFixed(6)}</span>`:'';
      const tkStr=usage.input?`<span>${usage.input}+${usage.output||0} tk</span>`:'';

      // Format text with simple markdown-like rendering
      txt=txt.replace(/```(\w*)\n?([\s\S]*?)```/g,'<pre><code>$2</code></pre>');
      txt=txt.replace(/`([^`]+)`/g,'<code>$1</code>');
      txt=txt.replace(/\n\n/g,'</p><p>');
      txt='<p>'+txt+'</p>';

      if(role==='user'){
        html+=`<div class="msg-row user">
          <div class="avatar">U</div>
          <div><div class="bubble">${txt.replace(/<p><\/p>/g,'')||'<em>(vacío)</em>'}</div>
          <div class="msg-footer">${tkStr} ${costStr}</div></div>
        </div>`;
      }else if(role==='assistant'){
        // Tool calls inline
        let tc='';
        for(const tc2 of toolCalls){
          tc+=`<details class="tool-block"><summary><i class="ph ph-wrench"></i> ${esc(tc2.name)}</summary><div class="tool-result" id="tc-${tc2.id}">⏳ esperando...</div></details>`;
          pendingToolResults[tc2.id]=true;
        }
        html+=`<div class="msg-row assistant">
          <div class="avatar">P</div>
          <div><div class="bubble">${txt.replace(/<p><\/p>/g,'')||''}${tc}
          <div class="msg-footer">${tkStr} ${costStr}</div></div></div>
        </div>`;
      }else if(role==='toolResult'){
        const elId='tc-'+msg.toolCallId;
        if(pendingToolResults[msg.toolCallId]){
          const resultText=Array.isArray(msg.content)?msg.content.map(c=>c.type==='text'?esc(c.text):'').join('\n'):esc(String(msg.content||''));
          html+=`<script>document.getElementById('${elId}')&&(document.getElementById('${elId}').textContent=${JSON.stringify(resultText)})</script>`;
          delete pendingToolResults[msg.toolCallId];
        }else{
          html+=`<div class="msg-row assistant"><div class="avatar">T</div><div><div class="bubble"><details class="tool-block"><summary><i class="ph ph-wrench"></i> ${esc(msg.toolName)}</summary><div class="tool-result">${Array.isArray(msg.content)?msg.content.map(c=>c.type==='text'?esc(c.text):'').join('\n'):esc(String(msg.content||''))}</div></details></div></div></div>`;
        }
      }
    }
  }
  body.innerHTML=html||'<div class="welcome">Sesión vacía</div>';
  body.scrollTop=body.scrollHeight;
}

