function renderDashboard(){
  if(!sessions.length)return;
  var totalTokens=0,totalCost=0;
  var modelCounts={};
  for(var i=0;i<sessions.length;i++){
    totalTokens+=sessions[i].total_tokens||0;
    totalCost+=sessions[i].total_cost||0;
    var mk=sessions[i].provider+'/'+sessions[i].model;
    modelCounts[mk]=(modelCounts[mk]||0)+1;
  }
  var topModel=Object.entries(modelCounts).sort(function(a,b){return b[1]-a[1]})[0]||['—'];
  var recent=sessions.slice().sort(function(a,b){return new Date(b.timestamp)-new Date(a.timestamp)}).slice(0,6);

  document.getElementById('dashboard').innerHTML=
    '<div class="dashboard">'+
    '<div class="dash-stats">'+
      '<div class="dash-stat"><div class="ds-value">'+sessions.length+'</div><div class="ds-label">Sesiones totales</div><div class="ds-sub">'+Object.keys(sessions.reduce(function(a,s){a[s.project]=1;return a},{})).length+' proyectos</div></div>'+
      '<div class="dash-stat"><div class="ds-value">'+(totalTokens/1000).toFixed(1)+'k</div><div class="ds-label">Tokens totales</div><div class="ds-sub">~'+Math.round(totalTokens/(sessions.length||1)).toLocaleString()+' / sesión</div></div>'+
      '<div class="dash-stat"><div class="ds-value">$'+totalCost.toFixed(2)+'</div><div class="ds-label">Costo total</div><div class="ds-sub">API usage acumulado</div></div>'+
      '<div class="dash-stat"><div class="ds-value" style="font-size:22px;font-family:var(--font-body);font-weight:500">'+esc(topModel[0])+'</div><div class="ds-label">Modelo más usado</div><div class="ds-sub">'+topModel[1]+' sesiones</div></div>'+
    '</div>'+
    '<div class="dash-recent"><h3>Sesiones recientes</h3><div class="dash-recent-grid">'+
      recent.map(function(s){return '<div class="dash-session-card" onclick="selectSession(\''+s.file.replace(/'/g,"\\'")+'\')"><div class="dsc-project">📁 '+esc(s.project)+'</div><div class="dsc-title">'+(s.name?esc(s.name):esc(s.first_user)||'(vacío)')+'</div><div class="dsc-meta"><span>'+formatDate(s.timestamp)+'</span><span>'+s.provider+'/'+s.model+'</span></div></div>';}).join('')+
    '</div></div></div>';
}

load().then(renderDashboard);

