  return text.split('\n').map(function(line){
    if(/^diff --git/.test(line)||/^(index |--- |\+\+\+ )/.test(line)||/^(new|old|similarity|rename|copy|deleted) /.test(line)) return '<span class="diff-meta">'+esc(line)+'</span>';
