content.text:
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"log"
	"mime"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/gin-gonic/gin"
)

var sessionsDir = filepath.Join(os.Getenv("HOME"), ".pi/agent/sessions")

func decodeProject(dirname string) string {
	// Dirname is --<path>-- where - encodes /
	inner := strings.Trim(dirname, "-")
	project := strings.ReplaceAll(inner, "-", "/")
	if strings.HasPrefix(project, "Users/") {
		project = "~/" + project[6:]
	}
	return project
}

type SessionSummary struct {
	ID            string  `json:"id"`
	File          string  `json:"file"`
	Project       string  `json:"project"`
	Timestamp     string  `json:"timestamp"`
	Name          *string `json:"name"`
	FirstUser     string  `json:"first_user"`
	Model         string  `json:"model"`
	Provider      string  `json:"provider"`
	UserMsgs      int     `json:"user_msgs"`
	AssistantMsgs int     `json:"assistant_msgs"`
	TotalTokens   int     `json:"total_tokens"`
	TotalCost     float64 `json:"total_cost"`
}

func parseSessionDir() []SessionSummary {
	entries, err := os.ReadDir(sessionsDir)
	if err != nil {
		return nil
	}

	var sessions []SessionSummary
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		project := decodeProject(entry.Name())
		projPath := filepath.Join(sessionsDir, entry.Name())

		files, err := os.ReadDir(projPath)
		if err != nil {
			continue
		}
		// Sort by name descending (newest first)
		sort.Slice(files, func(i, j int) bool {
			return files[i].Name() > files[j].Name()
		})

		for _, f := range files {
			if f.IsDir() || !strings.HasSuffix(f.Name(), ".jsonl") {
				continue
			}
			fpath := filepath.Join(projPath, f.Name())
			summary := parseSessionFile(fpath, project)
			if summary != nil {
				sessions = append(sessions, *summary)
			}
		}
	}
	return sessions
}

func parseSessionFile(fpath, project string) *SessionSummary {
	f, err := os.Open(fpath)
	if err != nil {
		return nil
	}
	defer f.Close()

	var lines []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.TrimSpace(line) != "" {
			lines = append(lines, line)
		}
	}
	if len(lines) == 0 {
		return nil
	}

	var header map[string]any
	if err := json.Unmarshal([]byte(lines[0]), &header); err != nil {
		return nil
	}
	if header["type"] != "session" {
		return nil
	}

	var sessionName *string
	firstUser := ""
	userMsgs, assistantMsgs := 0, 0
	totalInput, totalOutput := 0.0, 0.0
	totalCost := 0.0
	model, provider := "?", "?"

	for _, line := range lines[1:] {
		var entry map[string]any
		if err := json.Unmarshal([]byte(line), &entry); err != nil {
			continue
		}

		t, _ := entry["type"].(string)
		if t == "session_info" {
			if name, ok := entry["name"].(string); ok {
				n := name
				sessionName = &n
			}
			continue
		}
		if t != "message" {
			continue
		}

		msg, _ := entry["message"].(map[string]any)
		role, _ := msg["role"].(string)

		if role == "user" {
			userMsgs++
			if firstUser == "" {
				content := msg["content"]
				switch c := content.(type) {
				case string:
					firstUser = c
				case []any:
					var parts []string
					for _, item := range c {
						if m, ok := item.(map[string]any); ok {
							if m["type"] == "text" {
								if t, ok := m["text"].(string); ok {
									parts = append(parts, t)
								}
							}
						}
					}
					firstUser = strings.Join(parts, " ")
				}
				if len(firstUser) > 200 {
					firstUser = firstUser[:200]
				}
			}
		} else if role == "assistant" {
			assistantMsgs++
			if m, ok := msg["model"].(string); ok {
				model = m
			}
			if p, ok := msg["provider"].(string); ok {
				provider = p
			}
			if usage, ok := msg["usage"].(map[string]any); ok {
				if inp, ok := usage["input"].(float64); ok {
					totalInput += inp
				}
				if out, ok := usage["output"].(float64); ok {
					totalOutput += out
				}
				if cost, ok := usage["cost"].(map[string]any); ok {
					if t, ok := cost["total"].(float64); ok {
						totalCost += t
					}
				}
			}
		}
	}

	if firstUser == "" {
		firstUser = "(empty)"
	}

	id, _ := header["id"].(string)
	ts, _ := header["timestamp"].(string)

	return &SessionSummary{
		ID:            id,
		File:          fpath,
		Project:       project,
		Timestamp:     ts,
		Name:          sessionName,
		FirstUser:     firstUser,
		Model:         model,
		Provider:      provider,
		UserMsgs:      userMsgs,
		AssistantMsgs: assistantMsgs,
		TotalTokens:   int(totalInput + totalOutput),
		TotalCost:     totalCost,
	}
}

func main() {
	mime.AddExtensionType(".svg", "image/svg+xml")
	gin.SetMode(gin.ReleaseMode)
	r := gin.New()
	r.Use(gin.Recovery())

	// API: list sessions
	r.GET("/api/sessions", func(c *gin.Context) {
		c.JSON(http.StatusOK, parseSessionDir())
	})

	// API: get session lines
	r.GET("/api/session", func(c *gin.Context) {
		fpath := c.Query("file")
		if fpath == "" || !strings.HasPrefix(fpath, sessionsDir) {
			c.Status(http.StatusNotFound)
			return
		}
		if _, err := os.Stat(fpath); os.IsNotExist(err) {
			c.Status(http.StatusNotFound)
			return
		}

		f, err := os.Open(fpath)
		if err != nil {
			c.Status(http.StatusNotFound)
			return
		}
		defer f.Close()

		var lines []string
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := scanner.Text()
			if strings.TrimSpace(line) != "" {
				lines = append(lines, line)
			}
		}
		c.JSON(http.StatusOK, lines)
	})

	// Static files: serve frontend/dist if it exists
	// Try relative to binary location first (Docker), then relative to CWD (dev)
	distPath := filepath.Join("frontend", "dist")
	if _, err := os.Stat(distPath); os.IsNotExist(err) {
		distPath = filepath.Join("..", "frontend", "dist")
	}
	absDist, _ := filepath.Abs(distPath)
	if _, err := os.Stat(absDist); err == nil {
		// Serve specific static files
		// Root-level static files
		// Serve favicon directly (bypass Gin's file serving quirks)
		faviconPath := filepath.Join(absDist, "favicon.svg")
		r.GET("/favicon.svg", func(c *gin.Context) {
			c.File(faviconPath)
		})
		r.GET("/favicon.ico", func(c *gin.Context) {
			c.File(faviconPath)
		})
		// SPA: serve index.html for all other routes
		r.NoRoute(func(c *gin.Context) {
			c.File(filepath.Join(absDist, "index.html"))
		})
		r.Static("/assets", filepath.Join(absDist, "assets"))
		log.Println("Serving frontend from", absDist)
	} else {
		log.Println("Frontend dist not found at", absDist, ", API-only mode")
	}

	port := "8765"
	if len(os.Args) > 1 {
		port = os.Args[1]
	}
	fmt.Printf("Serving at http://localhost:%s\n", port)
	log.Fatal(r.Run("0.0.0.0:" + port))
}

import { ref, computed } from 'vue'
import type { SessionSummary } from '../types'

const sessions = ref<SessionSummary[]>([])
const loading = ref(false)
const error = ref<string | null>(null)
const selectedSession = ref<SessionSummary | null>(null)
const sessionLines = ref<string[]>([])

// Pins from localStorage
const pinnedIds = ref<Set<string>>(loadPins())

function loadPins(): Set<string> {
  try {
    const raw = localStorage.getItem('pi-sessions-pinned')
    if (raw) return new Set(JSON.parse(raw))
  } catch { /* empty */ }
  return new Set()
}

function savePins() {
  localStorage.setItem('pi-sessions-pinned', JSON.stringify([...pinnedIds.value]))
}

function togglePin(id: string) {
  if (pinnedIds.value.has(id)) {
    pinnedIds.value.delete(id)
  } else {
    pinnedIds.value = new Set([...pinnedIds.value, id])
  }
  savePins()
}

function isPinned(id: string): boolean {
  return pinnedIds.value.has(id)
}

// Grouped sessions for sidebar
interface SessionGroup {
  label: string
  sessions: SessionSummary[]
}

const groupedSessions = computed<SessionGroup[]>(() => {
  const now = new Date()
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate())
  const yesterday = new Date(today.getTime() - 86400000)
  const weekStart = new Date(today.getTime() - 7 * 86400000)

  const pinned: SessionSummary[] = []
  const todaySessions: SessionSummary[] = []
  const yesterdaySessions: SessionSummary[] = []
  const weekSessions: SessionSummary[] = []
  const older: SessionSummary[] = []

  for (const s of sessions.value) {
    if (isPinned(s.id)) {
      pinned.push(s)
      continue
    }
    const d = new Date(s.timestamp)
    if (d >= today) todaySessions.push(s)
    else if (d >= yesterday) yesterdaySessions.push(s)
    else if (d >= weekStart) weekSessions.push(s)
    else older.push(s)
  }

  pinned.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())

  const groups: SessionGroup[] = []
  if (pinned.length) groups.push({ label: '📌 Fijadas', sessions: pinned })
  if (todaySessions.length) groups.push({ label: 'Hoy', sessions: todaySessions })
  if (yesterdaySessions.length) groups.push({ label: 'Ayer', sessions: yesterdaySessions })
  if (weekSessions.length) groups.push({ label: 'Esta semana', sessions: weekSessions })
  if (older.length) groups.push({ label: 'Anterior', sessions: older })
  return groups
})

async function loadSessions() {
  loading.value = true
  error.value = null
  try {
    const res = await fetch('/api/sessions')
    if (!res.ok) throw new Error(`HTTP ${res.status}`)
    sessions.value = await res.json()
  } catch (e: any) {
    error.value = e.message
    sessions.value = []
  } finally {
    loading.value = false
  }
}

async function selectSession(s: SessionSummary) {
  selectedSession.value = s
  sessionLines.value = []
  try {
    const res = await fetch(`/api/session?file=${encodeURIComponent(s.file)}`)
    if (!res.ok) throw new Error(`HTTP ${res.status}`)
    sessionLines.value = await res.json()
  } catch (e: any) {
    error.value = e.message
    sessionLines.value = []
  }
}

export function useSessions() {
  return {
    sessions, sessionLines,
    loading,
    error,
    selectedSession,
    groupedSessions,
    pinnedIds,
    togglePin,
    isPinned,
    loadSessions,
    selectSession,
  }
}

