            if "019f29dc" in f:
                print(f"Found in {pdir}: {f}")
                files = [f]
                proj = pdir
                break

if not files:
    print("Session not found")
    exit()

with open(os.path.join(d, proj, files[0])) as f:
    lines = [json.loads(l) for l in f if l.strip()]

print(f"Session: {files[0]}")
print(f"Total lines: {len(lines)}")

# Show message flow with types
seq = []
for i, l in enumerate(lines):
    t = l.get("type")
    if t == "message":
        role = l.get("message", {}).get("role", "?")
        content = l["message"].get("content", "")
        if isinstance(content, list):
            types = {}
            for c in content:
                ct = c.get("type", "?")
                types[ct] = types.get(ct, 0) + 1
            seq.append(f"  [{i:3d}] {role:12s}: {types}")
        elif isinstance(content, str):
            seq.append(f"  [{i:3d}] {role:12s}: str({len(content)} chars)")
    elif t in ("model_change", "thinking_level_change", "compaction"):
        seq.append(f"  [{i:3d}] {t}")
    elif t == "session_info":
        seq.append(f"  [{i:3d}] session_info: {l.get('name', '?')}")

for s in seq[:80]:
    print(s)

# Count assistant-only-text messages
print("\n--- Analysis ---")
assistant_only_text = 0
assistant_with_tools = 0
for l in lines:
    if l.get("type") == "message" and l.get("message",{}).get("role") == "assistant":
        content = l["message"].get("content", "")
        if isinstance(content, list):
            has_tool = any(c.get("type")=="toolCall" for c in content)
            has_thinking = any(c.get("type")=="thinking" for c in content)
            has_text = any(c.get("type")=="text" and c.get("text","") for c in content)
            if has_tool or has_thinking:
                assistant_with_tools += 1
            else:
                assistant_only_text += 1
                # Show them
                texts = [c.get("text","")[:60] for c in content if c.get("type")=="text"]
                print(f"  PURE TEXT msg: {texts}")

print(f"\nAssistant with tools/thinking: {assistant_with_tools}")
print(f"Assistant pure text: {assistant_only_text}")
